namespace App\Events;

use App\Models\Review;
use Illuminate\Foundation\Events\Dispatchable;
use Illuminate\Queue\SerializesModels;

class ReviewPosted
{
    use Dispatchable, SerializesModels;

    public function __construct(public Review $review)
    {
    }
}

class NotifySeller implements ShouldQueue
{
    use InteractsWithQueue;

    public function handle(ReviewPosted $event): void
    {
        $review = $event->review;

        $review->product->seller->notify(new ReviewReceived($review));
    }
}

class LogReviewPosted
{
    public function handle(ReviewPosted $event): void
    {
        Log::info('review.posted', [
            'review_id' => $event->review->id,
            'product_id' => $event->review->product_id,
        ]);
    }
}

use App\Events\ReviewPosted;
use App\Listeners\LogReviewPosted;
use App\Listeners\NotifySeller;
use Illuminate\Support\Facades\Event;

public function boot(): void
{
    Event::listen(ReviewPosted::class, NotifySeller::class);
    Event::listen(ReviewPosted::class, LogReviewPosted::class);
}
